        if (uuid == database[i].uuid) {
            return database[i].doc || "N/A"; // หาก doc ไม่มีค่า ให้แสดงเป็น "N/A"
        }
    }
    return "N/A";
}
// ฟังก์ชันเพื่อค้นหา gfn
