var noti = "";
var timeNow = Date.now();
var offLine = 10 * 60 * 1000;
var times = {};

// ตรวจสอบว่า database มีค่าและเป็นอาร์เรย์
if (Array.isArray(database) && database.length > 0) {
    for (let index = 0; index < database.length; index++) {
        var device = database[index];

        // ตรวจสอบว่า device มีค่าหรือไม่
        if (!device || !device.uuid) {
            continue; // ข้ามไปถ้า device ไม่มีค่า
        }

        var uuid = device.uuid;
        var name = device.name || "Unknown"; // เผื่อกรณี name ไม่มีค่า
        var doc = device.doc || "-"; // กำหนดค่าเริ่มต้นถ้าไม่มี doc
        var gfn = device.gfn || "-"; // กำหนดค่าเริ่มต้นถ้าไม่มี gfn

        var lastTime = flow.get('uidHS' + uuid + ".timestamp") || 0; // ถ้าไม่มีค่ากำหนดเป็น 0
        times[uuid] = lastTime;

        if (timeNow - lastTime > offLine) {
            noti += `====================\n`;
            noti += `📍 **${name}**\n`;
            noti += `🔑 UUID : ${uuid}\n`;
            noti += `⚠️ STATUS : OFFLINE\n`;
            noti += `📄 Doc : ${doc}\n`;
            noti += `📊 Dashboard : ${gfn}\n`;
            noti += `====================\n\n`;

        }
    }

    // ตัดข้อความหากยาวเกิน 2000 ตัวอักษร
    if (noti.length > 2000) {
        noti = noti.substring(0, 1990);
    }

